INSERT INTO mind_definitions(mind_id,name,category,group_name,purpose,status,source_id,tags_json,disclaimer,definition_json) VALUES('alabama.crichton-leprechaun','CRICHTON LEPRECHAUN','folklore-lens','Alabama cryptids and legends','The 2006 Mobile neighborhood sensation and televised local folklore. Crichton is in Mobile, not central Alabama; the place anchor is preserved.','folklore-research-lens','devil-dog:alabama_legends:crichton-leprechaun','["Urban folklore / televised report","Crichton neighborhood / Mobile / Lower Alabama"]','','{"id":"alabama.crichton-leprechaun","name":"CRICHTON LEPRECHAUN","type":"folklore-lens","group":"Alabama cryptids and legends","purpose":"The 2006 Mobile neighborhood sensation and televised local folklore. Crichton is in Mobile, not central Alabama; the place anchor is preserved.","sourceId":"devil-dog:alabama_legends:crichton-leprechaun","tags":["Urban folklore / televised report","Crichton neighborhood / Mobile / Lower Alabama"],"baseIds":[],"status":"folklore-research-lens","disclaimer":""}');
