INSERT INTO mind_definitions(mind_id,name,category,group_name,purpose,status,source_id,tags_json,disclaimer,definition_json) VALUES('alabama.devildog-legend','THE DEVIL DOG OF ALABAMA','folklore-lens','Alabama cryptids and legends','John Nathan Tabor names himself The Devil Dog of Alabama. A separate Selma-area shadowy dog account belongs in the supplied folklore thread. The two are cross-linked without claiming an eyewitness identified Nathan as a creature.','folklore-research-lens','devil-dog:alabama_legends:devildog-legend','["Author-created identity + supplied folklore","Possom Hollar / Madison County; Selma-area story thread"]','','{"id":"alabama.devildog-legend","name":"THE DEVIL DOG OF ALABAMA","type":"folklore-lens","group":"Alabama cryptids and legends","purpose":"John Nathan Tabor names himself The Devil Dog of Alabama. A separate Selma-area shadowy dog account belongs in the supplied folklore thread. The two are cross-linked without claiming an eyewitness identified Nathan as a creature.","sourceId":"devil-dog:alabama_legends:devildog-legend","tags":["Author-created identity + supplied folklore","Possom Hollar / Madison County; Selma-area story thread"],"baseIds":[],"status":"folklore-research-lens","disclaimer":""}');
INSERT INTO mind_search(mind_id,name,group_name,purpose,tags) VALUES('alabama.devildog-legend','THE DEVIL DOG OF ALABAMA','Alabama cryptids and legends','John Nathan Tabor names himself The Devil Dog of Alabama. A separate Selma-area shadowy dog account belongs in the supplied folklore thread. The two are cross-linked without claiming an eyewitness identified Nathan as a creature.','Author-created identity + supplied folklore Possom Hollar / Madison County; Selma-area story thread');
INSERT INTO mind_definitions(mind_id,name,category,group_name,purpose,status,source_id,tags_json,disclaimer,definition_json) VALUES('alabama.falkville-metal-man','FALKVILLE METAL MAN','folklore-lens','Alabama cryptids and legends','October 17, 1973: police chief Jeff Greenhaw reported a reflective human-shaped figure and made four Polaroid images. A reported encounter and disputed pictures are not proof of an extraterrestrial visitor.','folklore-research-lens','devil-dog:alabama_legends:falkville-metal-man','["Reported UFO-era encounter","Falkville / Morgan County / Northern Alabama"]','','{"id":"alabama.falkville-metal-man","name":"FALKVILLE METAL MAN","type":"folklore-lens","group":"Alabama cryptids and legends","purpose":"October 17, 1973: police chief Jeff Greenhaw reported a reflective human-shaped figure and made four Polaroid images. A reported encounter and disputed pictures are not proof of an extraterrestrial visitor.","sourceId":"devil-dog:alabama_legends:falkville-metal-man","tags":["Reported UFO-era encounter","Falkville / Morgan County / Northern Alabama"],"baseIds":[],"status":"folklore-research-lens","disclaimer":""}');
INSERT INTO mind_search(mind_id,name,group_name,purpose,tags) VALUES('alabama.falkville-metal-man','FALKVILLE METAL MAN','Alabama cryptids and legends','October 17, 1973: police chief Jeff Greenhaw reported a reflective human-shaped figure and made four Polaroid images. A reported encounter and disputed pictures are not proof of an extraterrestrial visitor.','Reported UFO-era encounter Falkville / Morgan County / Northern Alabama');
INSERT INTO mind_definitions(mind_id,name,category,group_name,purpose,status,source_id,tags_json,disclaimer,definition_json) VALUES('alabama.huggin-molly','HUGGIN’ MOLLY','folklore-lens','Alabama cryptids and legends','The towering phantom woman of Abbeville: a local legend says she catches children outdoors after dark, hugs them, screams, then disappears. This is a legend, not a confirmed apparition.','folklore-research-lens','devil-dog:alabama_legends:huggin-molly','["Phantom / local ghost legend","Abbeville / Henry County / Lower Alabama"]','','{"id":"alabama.huggin-molly","name":"HUGGIN’ MOLLY","type":"folklore-lens","group":"Alabama cryptids and legends","purpose":"The towering phantom woman of Abbeville: a local legend says she catches children outdoors after dark, hugs them, screams, then disappears. This is a legend, not a confirmed apparition.","sourceId":"devil-dog:alabama_legends:huggin-molly","tags":["Phantom / local ghost legend","Abbeville / Henry County / Lower Alabama"],"baseIds":[],"status":"folklore-research-lens","disclaimer":""}');
INSERT INTO mind_search(mind_id,name,group_name,purpose,tags) VALUES('alabama.huggin-molly','HUGGIN’ MOLLY','Alabama cryptids and legends','The towering phantom woman of Abbeville: a local legend says she catches children outdoors after dark, hugs them, screams, then disappears. This is a legend, not a confirmed apparition.','Phantom / local ghost legend Abbeville / Henry County / Lower Alabama');
