INSERT INTO mind_definitions(mind_id,name,category,group_name,purpose,status,source_id,tags_json,disclaimer,definition_json) VALUES('alabama.toby-lily-ghost','TOBY & LILY / THE GHOST DOG STORY','folklore-lens','Alabama cryptids and legends','The supplied ghost account names Toby as a farmer and Lily (also Lilly) as his beloved Labrador whose spirit lingers near the farm. In the expanded Devil Dog canon, Toby and Lily are Nathan’s best buddies. Preserve the ghost-story characters and the companion versions without silently merging their biographies.','folklore-research-lens','devil-dog:alabama_legends:toby-lily-ghost','["Supplied ghost story + main cast","Farmhouse ghost-story setting; specific location not established"]','','{"id":"alabama.toby-lily-ghost","name":"TOBY & LILY / THE GHOST DOG STORY","type":"folklore-lens","group":"Alabama cryptids and legends","purpose":"The supplied ghost account names Toby as a farmer and Lily (also Lilly) as his beloved Labrador whose spirit lingers near the farm. In the expanded Devil Dog canon, Toby and Lily are Nathan’s best buddies. Preserve the ghost-story characters and the companion versions without silently merging their biographies.","sourceId":"devil-dog:alabama_legends:toby-lily-ghost","tags":["Supplied ghost story + main cast","Farmhouse ghost-story setting; specific location not established"],"baseIds":[],"status":"folklore-research-lens","disclaimer":""}');
INSERT INTO mind_search(mind_id,name,group_name,purpose,tags) VALUES('alabama.toby-lily-ghost','TOBY & LILY / THE GHOST DOG STORY','Alabama cryptids and legends','The supplied ghost account names Toby as a farmer and Lily (also Lilly) as his beloved Labrador whose spirit lingers near the farm. In the expanded Devil Dog canon, Toby and Lily are Nathan’s best buddies. Preserve the ghost-story characters and the companion versions without silently merging their biographies.','Supplied ghost story + main cast Farmhouse ghost-story setting; specific location not established');
